package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.nio.charset.StandardCharsets;import static org.junit.jupiter.api.Assertions.*;
class LegacyReportFileReaderTest {
 @TempDir Path root;static final byte[] PDF="%PDF-1.4\nowned report bytes\n%%EOF\n".getBytes(StandardCharsets.UTF_8);
 @Test void readsLocalLegacyUrlWithoutChangingBytesOrUnicodeFilename()throws Exception{Files.createDirectories(root.resolve("2024"));Files.write(root.resolve("2024/中文报告 1.pdf"),PDF);var reader=new LegacyReportFileReader(root.toString(),1024);var result=reader.read("https://old.example.invalid/Content/FilePdf/2024/%E4%B8%AD%E6%96%87%E6%8A%A5%E5%91%8A%201.pdf");assertEquals("中文报告 1.pdf",result.filename());assertArrayEquals(PDF,result.data());}
 @Test void missingUnconfiguredAndIncompleteArtifactsNeverBecomePlaceholderPdf()throws Exception{assertEquals(409,assertThrows(BusinessException.class,()->new LegacyReportFileReader("",1024).read("/Content/FilePdf/missing.pdf")).getCode());var reader=new LegacyReportFileReader(root.toString(),1024);assertEquals(404,assertThrows(BusinessException.class,()->reader.read("/Content/FilePdf/missing.pdf")).getCode());Files.writeString(root.resolve("unfinished.pdf"),"%PDF-1.4 not finished");assertEquals(422,assertThrows(BusinessException.class,()->reader.read("/Content/FilePdf/unfinished.pdf")).getCode());Files.write(root.resolve("large.pdf"),PDF);assertEquals(413,assertThrows(BusinessException.class,()->new LegacyReportFileReader(root.toString(),8).read("/Content/FilePdf/large.pdf")).getCode());}
 @Test void traversalAndExternalSymlinksAreRejected()throws Exception{var reader=new LegacyReportFileReader(root.toString(),1024);for(String ref:new String[]{"/Content/FilePdf/../outside.pdf","https://old.invalid/Content/FilePdf/%2e%2e/outside.pdf","file:///tmp/outside.pdf","/unmapped/path.pdf"})assertThrows(BusinessException.class,()->reader.read(ref));var outside=Files.createTempFile(root.getParent(),"petlis-owned-report-",".pdf");try{Files.write(outside,PDF);Files.createSymbolicLink(root.resolve("linked.pdf"),outside);assertEquals(403,assertThrows(BusinessException.class,()->reader.read("/Content/FilePdf/linked.pdf")).getCode());}finally{Files.deleteIfExists(outside);}}
}
